import logging
import math
import time
from collections.abc import Callable
from typing import TypeVar

from . import clock
from .errors import InvalidInput, PermanentError, TransientError

logger = logging.getLogger(__name__)

T = TypeVar("T")

_MAX_TOTAL_WAIT_SECONDS = 60.0


def _elapsed_seconds(started_at: object) -> float:
    elapsed = clock.now() - started_at
    seconds = elapsed.total_seconds() if hasattr(elapsed, "total_seconds") else float(elapsed)
    return max(0.0, seconds)


def call_with_retry(fn: Callable[[], T], attempts: int, base_delay: float) -> T:
    """Call fn with bounded exponential-backoff retries for transient failures."""
    if not callable(fn):
        raise InvalidInput("fn must be callable")
    if isinstance(attempts, bool) or not isinstance(attempts, int) or attempts < 1:
        raise InvalidInput("attempts must be a positive integer")
    if (
        isinstance(base_delay, bool)
        or not isinstance(base_delay, (int, float))
        or not math.isfinite(base_delay)
        or base_delay < 0
    ):
        raise InvalidInput("base_delay must be a finite non-negative number")

    started_at = clock.now()
    scheduled_wait = 0.0
    delay = float(base_delay)

    for attempt in range(attempts):
        try:
            return fn()
        except PermanentError:
            raise
        except TransientError:
            if attempt == attempts - 1:
                raise

            elapsed = _elapsed_seconds(started_at)
            remaining = _MAX_TOTAL_WAIT_SECONDS - max(elapsed, scheduled_wait)
            if remaining <= 0:
                raise

            wait_time = min(delay, remaining)
            logger.warning(
                "Transient failure calling function; retrying",
                extra={
                    "attempt": attempt + 1,
                    "attempts": attempts,
                    "delay_seconds": wait_time,
                },
                exc_info=True,
            )
            if wait_time > 0:
                time.sleep(wait_time)
                scheduled_wait += wait_time

            delay = min(delay * 2, _MAX_TOTAL_WAIT_SECONDS)

    raise PermanentError("retry loop completed without a result")

import copy
import logging

from errors import InvalidInput

logger = logging.getLogger(__name__)


def merge_config(base: dict, override: dict) -> dict:
    """Recursively merge override onto base, returning a new dict without mutating inputs."""
    if not isinstance(base, dict) or not isinstance(override, dict):
        logger.error("merge_config received non-dict input: base=%r override=%r", type(base), type(override))
        raise InvalidInput("Both base and override must be dicts")

    result = copy.deepcopy(base)

    for key, override_value in override.items():
        if key in result and isinstance(result[key], dict) and isinstance(override_value, dict):
            result[key] = merge_config(result[key], override_value)
        else:
            result[key] = copy.deepcopy(override_value)

    return result

import copy
import logging

from errors import InvalidInput

logger = logging.getLogger(__name__)


def merge_config(base: dict, override: dict) -> dict:
    """Deep-merge override onto base without mutating either input."""
    if not isinstance(base, dict) or not isinstance(override, dict):
        raise InvalidInput("base and override must both be dictionaries")

    return _merge_dicts(base, override)


def _merge_dicts(base: dict, override: dict) -> dict:
    result = copy.deepcopy(base)

    for key, override_value in override.items():
        base_value = base.get(key)

        if (
            key in base
            and isinstance(base_value, dict)
            and isinstance(override_value, dict)
        ):
            result[key] = _merge_dicts(base_value, override_value)
        else:
            result[key] = copy.deepcopy(override_value)

    return result

