import csv
import logging
from dataclasses import dataclass
from typing import Protocol

from errors import InvalidInput

logger = logging.getLogger(__name__)


class Sink(Protocol):
    """Destination for validated CSV rows."""

    def validate(self, row: list[str]) -> bool:
        """Return whether a CSV row is valid."""

    def write(self, row: list[str]) -> None:
        """Write a validated CSV row."""


@dataclass(frozen=True)
class IngestReport:
    """Summary of a CSV ingestion operation."""

    rows_read: int
    rows_written: int
    rows_skipped: int


def ingest(path: str, sink: Sink) -> IngestReport:
    """Stream valid CSV rows from path to sink and return ingestion counts."""
    if not isinstance(path, str) or not path.strip() or "\x00" in path:
        raise InvalidInput("path must be a non-empty string without null bytes")

    if sink is None or not callable(getattr(sink, "validate", None)) or not callable(
        getattr(sink, "write", None)
    ):
        raise InvalidInput("sink must provide callable validate and write methods")

    rows_read = 0
    rows_written = 0
    rows_skipped = 0

    try:
        file_handle = open(path, "r", encoding="utf-8", newline="")
    except (OSError, UnicodeError) as exc:
        raise InvalidInput(f"unable to open CSV file: {path}") from exc

    try:
        with file_handle:
            reader = csv.reader(file_handle, strict=True)

            while True:
                try:
                    row = next(reader)
                except StopIteration:
                    break
                except (OSError, UnicodeError, csv.Error) as exc:
                    raise InvalidInput(f"unable to read CSV file: {path}") from exc

                rows_read += 1

                try:
                    is_valid = sink.validate(row)
                except InvalidInput:
                    is_valid = False

                if not is_valid:
                    rows_skipped += 1
                    logger.debug("Skipping invalid CSV row")
                    continue

                sink.write(row)
                rows_written += 1
    except OSError as exc:
        raise InvalidInput(f"unable to close CSV file: {path}") from exc

    return IngestReport(
        rows_read=rows_read,
        rows_written=rows_written,
        rows_skipped=rows_skipped,
    )

"""Duplicate suppression for ordered event streams.

Suppresses events sharing the same `event.key` when they occur within
`window_seconds` of a prior occurrence of that key. The input stream is
assumed to be ordered by timestamp and may be unbounded; results are
yielded lazily as soon as an event is known to survive.
"""

import logging
from typing import Any, Dict, Iterable, Iterator

from errors import InvalidInput
from models import Event

logger = logging.getLogger(__name__)


def _delta_seconds(later: Any, earlier: Any) -> float:
    """Return the number of seconds between two timestamps, supporting datetimes and numeric epochs."""
    delta = later - earlier
    if hasattr(delta, "total_seconds"):
        return delta.total_seconds()
    if isinstance(delta, (int, float)):
        return float(delta)
    raise InvalidInput(f"unsupported timestamp type for delta computation: {type(later)!r}")


def dedupe(events: Iterable[Event], window_seconds: float) -> Iterator[Event]:
    """Yield events from `events`, suppressing duplicates whose key was seen within `window_seconds` of a prior occurrence."""
    if events is None:
        raise InvalidInput("events must not be None")
    if not isinstance(window_seconds, (int, float)) or isinstance(window_seconds, bool):
        raise InvalidInput(f"window_seconds must be a non-negative number, got {window_seconds!r}")
    if window_seconds < 0:
        raise InvalidInput(f"window_seconds must be non-negative, got {window_seconds!r}")

    last_seen: Dict[Any, Any] = {}

    for event in events:
        if event is None:
            raise InvalidInput("event must not be None")

        key = getattr(event, "key", None)
        timestamp = getattr(event, "timestamp", None)
        if key is None or timestamp is None:
            raise InvalidInput(
                f"event must have non-None 'key' and 'timestamp' attributes: {event!r}"
            )

        prior_timestamp = last_seen.get(key)
        if prior_timestamp is not None:
            elapsed = _delta_seconds(timestamp, prior_timestamp)
            if elapsed < 0:
                raise InvalidInput(
                    f"events must be ordered by timestamp; got out-of-order timestamp for key={key!r}"
                )
            if elapsed < window_seconds:
                logger.debug(
                    "suppressing duplicate event key=%r elapsed=%.6fs window=%.6fs",
                    key,
                    elapsed,
                    window_seconds,
                )
                continue

        last_seen[key] = timestamp
        yield event

