from collections import deque
from collections.abc import Iterable, Iterator
from math import isfinite
from numbers import Real
from typing import Hashable

from .errors import InvalidInput
from .models import Event


def dedupe(events: Iterable[Event], window_seconds: float) -> Iterator[Event]:
    """Yield events whose keys have not appeared within the deduplication window."""
    if isinstance(window_seconds, bool) or not isinstance(window_seconds, Real):
        raise InvalidInput("window_seconds must be a finite non-negative number")

    window = float(window_seconds)
    if not isfinite(window) or window < 0:
        raise InvalidInput("window_seconds must be a finite non-negative number")

    try:
        iterator = iter(events)
    except TypeError as exc:
        raise InvalidInput("events must be an iterable of Event instances") from exc

    return _dedupe_events(iterator, window)


def _dedupe_events(events: Iterator[Event], window_seconds: float) -> Iterator[Event]:
    recent: dict[Hashable, tuple[object, int]] = {}
    occurrences: deque[tuple[object, int, Hashable]] = deque()
    previous_timestamp: object | None = None
    sequence = 0

    for event in events:
        try:
            key = event.key
            timestamp = event.timestamp
        except AttributeError as exc:
            raise InvalidInput("each event must provide key and timestamp attributes") from exc

        try:
            hash(key)
        except TypeError as exc:
            raise InvalidInput("event.key must be hashable") from exc

        if previous_timestamp is None:
            _elapsed_seconds(timestamp, timestamp)
        else:
            if _elapsed_seconds(timestamp, previous_timestamp) < 0:
                raise InvalidInput("events must be ordered by timestamp")

        while occurrences:
            oldest_timestamp, oldest_sequence, oldest_key = occurrences[0]
            if _elapsed_seconds(timestamp, oldest_timestamp) < window_seconds:
                break

            occurrences.popleft()
            current = recent.get(oldest_key)
            if current is not None and current[1] == oldest_sequence:
                del recent[oldest_key]

        prior = recent.get(key)
        duplicate = (
            prior is not None
            and _elapsed_seconds(timestamp, prior[0]) < window_seconds
        )

        sequence += 1
        recent[key] = (timestamp, sequence)
        occurrences.append((timestamp, sequence, key))
        previous_timestamp = timestamp

        if not duplicate:
            yield event


def _elapsed_seconds(newer: object, older: object) -> float:
    try:
        delta = newer - older  # type: ignore[operator]
        seconds = delta.total_seconds() if hasattr(delta, "total_seconds") else float(delta)
        seconds = float(seconds)
    except (AttributeError, OverflowError, TypeError, ValueError) as exc:
        raise InvalidInput("event timestamps must support subtraction") from exc

    if not isfinite(seconds):
        raise InvalidInput("event timestamps must produce finite differences")

    return seconds

def bulk_update(store: Store, updates: list[Update]) -> BulkResult:
    """Apply updates and report each successful or failed operation."""
    if not isinstance(store, Store):
        raise InvalidInput("store must be a Store instance")

    if not isinstance(updates, list):
        raise InvalidInput("updates must be a list")

    if any(not isinstance(update, Update) for update in updates):
        raise InvalidInput("updates must contain only Update instances")

    succeeded: list[Update] = []
    failed: list[tuple[Update, DomainError]] = []

    for update in updates:
        try:
            store.update(update)
        except DomainError as error:
            failed.append((update, error))
        else:
            succeeded.append(update)

    return BulkResult(succeeded=succeeded, failed=failed)
